entries[439733] = { ["name"] = "Tree of Life", ["text"] = "13% of base mana\nInstant\nShapeshift into the Tree of Life. While in this form you increase healing received by 10% for all party members within 45 yards, Wild Growth healing is increased by 60%, your heal over time spells cost 20% less, you gain 25% increased Spirit, you gain 200% increased armor, and you cannot cast harmful spells.\n\nThe act of shapeshifting frees the caster of Polymorph and Movement Impairing effects." }
entries[439734] = { ["name"] = "Tree of Life (Passive)", ["text"] = "Requires Tree Form\nModifies Power Cost -19%:\nLifebloom , Regrowth , Regrowth , Regrowth , Regrowth , Regrowth , Regrowth , Regrowth , Regrowth , Regrowth , Rejuvenation , Rejuvenation , Rejuvenation , Rejuvenation , Rejuvenation , Rejuvenation , Rejuvenation , Rejuvenation , Rejuvenation , Rejuvenation , Rejuvenation , Tranquility , Tranquility , Tranquility , Tranquility , Wild Growth , Wild Growth , Wild Growth\n\nModifies Periodic Damage/Healing Done +61%:\nWild Growth , Wild Growth , Wild Growth" }
