entries[439748] = { ["name"] = "Starfall", ["text"] = "39% of base mana\nInstant 1.5 min cooldown\nYou summon a flurry of stars from the sky over 10 sec, striking targets within 30 yards of your location, each dealing [source value] to [source value] Arcane damage to its target and [source value] Arcane damage to all other enemies within 5 yards. Maximum 20 stars.\n\nShapeshifting or mounting cancels the effect. Any effect which causes you to lose control of your character will suppress the Starfall effect.\n\nBenefits from and triggers most talents and effects that trigger or benefit from Moonfire.", ["unresolvedValues"] = true }
entries[439753] = { ["name"] = "Starfall", ["text"] = "Unlimited range\nInstant\nYou summon a flurry of stars from the sky on all targets within 30 yards of the caster, each dealing 46 to 54 Arcane damage. Also causes 46 to 54 Arcane damage to all other enemies within 0 yards of the enemy target. Maximum 20 stars. Lasts until canceled." }
